"""Plain-language explanations the code tracer shows next to a line.

Each entry is  key: (title, text). The viewer matches them to what it finds on a line:
YAML syntax, play and task keywords, modules and their options, Jinja filters and tests,
Ansible's built-in variables, Bash constructs, and the Oracle tools the scripts call.
Add or reword entries here, then run build.py again.
"""

# --- YAML: the file format every Ansible file is written in ---------------------------
YAML = {
    "comment": ("Comment", "A line starting with # is a note for people. Ansible ignores it. In this repo the comments explain why a task exists, so they are worth reading."),
    "doc_start": ("---  (start of a YAML document)", "Marks the start of a YAML file. It is optional, but most Ansible files begin with it."),
    "list_item": ("- (list item)", "A dash starts one item of a list. In a tasks file, every top-level dash is one task. In a playbook, every top-level dash is one play."),
    "mapping": ("key: value", "YAML's basic building block: a name, a colon, then its value. Ansible reads the key to know what you are setting (a keyword such as when, a module name, or a module option)."),
    "folded": (">- (folded text)", "The value continues on the indented lines below. '>' joins those lines into one line with spaces, and '-' drops the final newline. Used for long messages and long Jinja expressions so they stay readable."),
    "literal": ("| (literal text)", "The value continues on the indented lines below, and the line breaks are kept exactly. Used for scripts, SQL and multi-line file content."),
    "continuation": ("Continuation line", "This line is part of a multi-line value that started on a line above (look for the key with > or | at the end). It is text or a Jinja expression, not a new key."),
    "flow_map": ("{ ... } (inline mapping)", "A whole mapping written on one line: {name: zdlra_patch, tasks_from: run_phase} is the same as writing each key on its own indented line."),
    "flow_list": ("[ ... ] (inline list)", "A whole list written on one line: [precheck, quiesce] is the same as a dash per item on separate lines."),
    "quoted": ("Quotes around a value", "A value that starts with {{ must be quoted, or YAML mistakes the { for an inline mapping. Quotes are also used when a value contains a colon followed by a space."),
}

