# --- Bash: the shell scripts --------------------------------------------------------------
# Each is (regex, title, text); the viewer shows every one that matches the line.
BASH = [
    (r"^#!", "#! (shebang)", "The first line says which program runs the script: here bash."),
    (r"^\s*#", "Comment", "Bash ignores everything after # on a line."),
    (r"\bset -[a-zA-Z]*e", "set -e / -u / -o pipefail", "Safety switches: -e exits on the first failing command, -u treats an unset variable as an error, -o pipefail makes a pipe fail if any part fails."),
    (r"^\s*(function\s+)?[A-Za-z_][A-Za-z0-9_]*\s*\(\)\s*\{?", "Function definition", "name() { ... } defines a function. Call it like a command: name arg1 arg2. Inside, the arguments are $1, $2, ... and $@ is all of them."),
    (r"\blocal\b", "local", "Makes the variable exist only inside this function, so it doesn't overwrite one of the same name elsewhere."),
    (r"\breadonly\b|\bdeclare -r\b", "readonly", "A variable that can't be changed after this line."),
    (r"\bdeclare\b", "declare", "Declares a variable with attributes: -a array, -A associative array (dict), -i integer, -g global."),
    (r"\bexport\b", "export", "Makes the variable visible to programs this script starts."),
    (r"^\s*(if|elif)\b", "if / elif / else / fi", "Runs the block if the command after 'if' succeeds (exit code 0). [[ ... ]] and [ ... ] are such commands: tests."),
    (r"\[\[", "[[ ... ]] (test)", "Bash's test: -z \"$x\" (empty), -n (not empty), -f (file exists), -d (folder exists), -e (exists), -s (non-empty file), == (equal / glob match), =~ (regex match), != (not equal), && and || inside."),
    (r"(^|\s)\[ ", "[ ... ] (test)", "The older test command: -z, -n, -f, -d, = and -eq, -lt, -gt for numbers."),
    (r"\(\(", "(( ... )) (arithmetic)", "Integer math and comparisons: (( n > 3 )), (( count++ ))."),
    (r"^\s*case\b", "case ... in ... esac", "Compare a value against patterns: each 'pattern)' branch ends with ';;'. '*)' is the catch-all."),
    (r"^\s*[^()]*\)\s*$|;;", "case branch", "One branch of a case statement: the pattern before ')', the commands until ';;'."),
    (r"^\s*for\b", "for loop", "for x in a b c; do ...; done repeats the body with x set to each value."),
    (r"^\s*while\b", "while loop", "Repeats the body while the command succeeds. 'while read -r line' reads input line by line."),
    (r"\bread\b", "read", "Reads a line of input into variables. -r keeps backslashes, -p shows a prompt, -t sets a timeout."),
    (r"\bmapfile\b|\breadarray\b", "mapfile", "Reads lines into an array: mapfile -t arr < file."),
    (r"\$\(", "$( ... ) (command substitution)", "Runs the command inside and puts its output here, as text."),
    (r"\$\{[^}]*:-", "${var:-default}", "The variable's value, or the default if it is unset or empty."),
    (r"\$\{[^}]*:=", "${var:=default}", "Like :- but also assigns the default to the variable."),
    (r"\$\{[^}]*:\?", "${var:?message}", "Fails with the message if the variable is unset or empty."),
    (r"\$\{[^}]*(##?|%%?)", "${var#...} / ${var%...}", "Trims a pattern from the start (#) or end (%) of the value. ## and %% trim the longest match."),
    (r"\$\{[^}]*//?", "${var/a/b}", "Replaces a with b in the value (// replaces every match)."),
    (r"\$\{#", "${#var}", "The length of the value (or ${#arr[@]}: number of items)."),
    (r"\[@\]", "${arr[@]}", "All items of an array. Quote it, \"${arr[@]}\", so each item stays one argument."),
    (r"\$\?", "$?", "The exit code of the last command: 0 = success."),
    (r"\$#", "$#", "How many arguments the script or function got."),
    (r"\$@|\$\*", "$@", "All the arguments. \"$@\" keeps each as a separate word."),
    (r"\$[0-9]", "$1, $2, ...", "Positional arguments: the first, second ... argument of the script or function."),
    (r"\$\$", "$$", "This shell's process ID."),
    (r"\bshift\b", "shift", "Drops $1 and moves the other arguments down one."),
    (r"\breturn\b", "return", "Leaves the function with this exit code (0 = success)."),
    (r"\bexit\b", "exit", "Ends the whole script with this exit code."),
    (r"\btrap\b", "trap", "Runs a command when the script gets a signal (INT = Ctrl-C, TERM, HUP) or exits (EXIT). Used to clean up, or to ignore signals so nothing cuts a step short."),
    (r"\|\|", "||", "Run the right side only if the left side failed. 'cmd || true' ignores a failure; 'cmd || die ...' stops on one."),
    (r"&&", "&&", "Run the right side only if the left side worked."),
    (r"2>&1", "2>&1", "Send errors (stream 2) to the same place as normal output (stream 1)."),
    (r">/dev/null|> /dev/null", ">/dev/null", "Throw the output away."),
    (r"(^|[^<])<<-?\s*['\"]?[A-Z_]+", "<<EOF (here-document)", "The lines until the closing word are fed to the command as input. With the word quoted ('EOF'), $variables inside are not expanded."),
    (r"<<<", "<<< (here-string)", "Feeds this text to the command as its input."),
    (r"(^|[^>&0-9])>>", ">> (append)", "Add the output to the end of the file."),
    (r"(^|[^>&0-9-])>\s*[\"$/A-Za-z]", "> (redirect)", "Write the output to a file, replacing what was there."),
    (r"\|\s*\w", "| (pipe)", "The output of the left command becomes the input of the right one."),
    (r"(^|\s)(source|\.)\s+[\"$/]", "source", "Runs another file in this same shell, so the variables it sets are visible here. Used to read the .conf file."),
    (r"\bgrep\b", "grep", "Prints the lines that match a pattern. -q prints nothing (just the exit code), -E extended regex, -c counts, -v inverts, -F plain text."),
    (r"\bsed\b", "sed", "Stream editor: transforms text line by line, usually s/old/new/ substitutions."),
    (r"\bawk\b", "awk", "A small language for processing text by columns: $1 is the first column."),
    (r"\bprintf\b", "printf", "Prints formatted text: %s is replaced by the next argument, \\n is a newline."),
    (r"\becho\b", "echo", "Prints its arguments."),
    (r"\bscreen\b", "screen", "A terminal multiplexer: runs a program in a session that keeps going if you disconnect. 'screen -dmS name cmd' starts it detached, 'screen -r name' reattaches, Ctrl-A then d detaches again."),
    (r"\bnohup\b", "nohup", "Runs a command that ignores the hangup signal, so it keeps running after logout."),
    (r"\bssh\b", "ssh", "Runs a command on another machine. BatchMode=yes means never prompt for a password."),
    (r"\bscp\b", "scp", "Copies files between machines over ssh."),
    (r"\bmkdir -p\b", "mkdir -p", "Creates a folder, and any parent folders, with no error if it already exists."),
    (r"\bsleep\b", "sleep", "Waits this many seconds."),
    (r"\bkill\b", "kill", "Sends a signal to a process. kill -0 sends nothing; it only checks the process exists."),
    (r"\bdate\b", "date", "Prints the date and time; +%Y%m%d... chooses the format."),
    (r"\btee\b", "tee", "Writes its input both to the screen and to a file."),
    (r"\bsha256sum\b", "sha256sum", "A checksum of a file: any change to the file changes it."),
    (r"\bunzip\b", "unzip", "Extracts a zip file."),
    (r"\bxargs\b", "xargs", "Turns input lines into command arguments."),
    (r"\btr\b", "tr", "Translates or deletes characters."),
    (r"\bcut\b", "cut", "Picks columns or characters from each line."),
    (r"\bhead\b", "head", "The first lines of the input."),
    (r"\btail\b", "tail", "The last lines of the input. tail -f follows a growing file."),
    (r"\bmktemp\b", "mktemp", "Creates a temporary file or folder with a unique name."),
    (r"\bflock\b", "flock", "A lock, so two copies of the script can't run at once."),
]

# --- The Oracle and site tools the code calls ---------------------------------------------
TOOLS = {
    "racli": ("racli (Recovery Appliance CLI)", "Oracle's command-line tool for the ZDLRA software: racli version, racli run preinstall, racli alter appliance, racli update appliance (the 2-hour patch)."),
    "patchmgr": ("patchmgr (Exadata patch manager)", "Oracle's tool that patches Exadata storage cells, switches and compute nodes. It runs from one node and patches others. It must never be cut short, which is why this repo runs it in a detached screen session."),
    "dcli": ("dcli (distributed CLI)", "Runs the same command on many cells or nodes at once, listed in a group file (-g cell_group)."),
    "imageinfo": ("imageinfo", "Shows the Exadata image version of a cell or compute node; used to check a patch worked."),
    "emcli": ("emcli (Enterprise Manager CLI)", "Command-line access to Oracle Enterprise Manager (OEM): log in, create or stop blackouts, suspend or resume jobs."),
    "sqlplus": ("sqlplus", "Oracle's SQL command-line client. Here it is run by zdlra_sql.sh as the raAutomation user."),
    "crsctl": ("crsctl", "Oracle Clusterware control: crsctl stat res -t shows the state of every cluster resource."),
    "cellcli": ("cellcli", "The command-line interface on a storage cell."),
    "sr_jobs_new.ksh": ("sr_jobs_new.ksh", "A site script on the OEM server that writes a script of emcli commands to suspend or resume an appliance's backup jobs."),
    "blackout": ("OEM blackout", "Tells Enterprise Manager to ignore alerts for targets during maintenance, so patching doesn't page anyone."),
    "zdlra": ("ZDLRA", "Zero Data Loss Recovery Appliance: Oracle's backup appliance (compute nodes, storage cells and switches, managed with racli)."),
}

